  m.querySelector('#h3ds-purge-confirm').onclick = function () {
    closeModal();
    if (writeInFlight(ui)) return;
    var keys = keysAllowedForPurge(rows, snapshot);
    if (!keys.length) {
      showMessage('error', 'Unable to purge data.');
      return;
    }
    ui.op = { kind: 'purging', keys: keys.slice() };
    window.__h3dsUi = ui;
    renderActions();
    renderTable();
    showMessage('info', 'Purging ' + keys.length + ' data source(s)\u2026');
    var arraySql = 'ARRAY[' + keys.map(function (k) { return "'" + sqlEscapeKey(k) + "'"; }).join(',') + ']::text[]';
    var sql = selectedOnly
      ? 'SELECT heart360tk_reporting.delete_leaf_node_data(' + arraySql + ',TRUE,FALSE) AS result;'
      : "SELECT heart360tk_reporting.delete_leaf_node_data(ARRAY['PURGE_EVERYTHING']::text[],FALSE,TRUE) AS result;";
    var purgeCount = keys.length;
    var purgeRefId = selectedOnly ? 'PURGE_SELECTED' : 'PURGE_EVERYTHING';
    runQuery(sql, purgeRefId).then(function (body) {
      if (!rootLive()) return;
      if (!purgeOutcomeOk(body, purgeRefId)) {
        showMessage('error', 'Unable to purge data.');
        return;
      }
      rows.forEach(function (r) {
        if (keys.indexOf(r.source_key) !== -1) r.data_status = 'no_data';
      });
      ui.selected = ui.selected.filter(function (k) { return keys.indexOf(k) === -1; });
      window.__h3dsUi = ui;
      showMessage('success', 'Data purged for ' + purgeCount + ' data source(s).');
    }).catch(function () {
      if (rootLive()) showMessage('error', 'Unable to purge data.');
    }).finally(function () {
      finishOpAndRender();
    });
  };
}

function render() {
  renderActions();
  renderSummary();
  renderFilters();
  renderTable();
}

if (searchInput && !searchInput.dataset.wired) {
  searchInput.dataset.wired = '1';
  if (searchInput.value !== ui.search) searchInput.value = ui.search;
  var debounceTimer;
  searchInput.oninput = function (e) {
    clearTimeout(debounceTimer);
    var val = e.target.value;
    debounceTimer = setTimeout(function () {
      ui.search = val;
      ui.page = 1;
      window.__h3dsUi = ui;
      renderTable();
    }, 150);
  };
} else if (searchInput && document.activeElement !== searchInput) {
  searchInput.value = ui.search;
}

forceBtn.onclick = writeForceImport;
purgeBtn.onclick = confirmAndPurge;
render();

